function AlmosaferLogo({ type = "wordmark", variant = "colour", lang = "en", width, className, ...props }) {
	const logo = logos[type === "wordmark" ? `wordmark:${variant}:${lang}` : `${type}:${variant}`];
	if (!logo) return null;
	const [, , vbW, vbH] = logo.viewBox.split(" ").map(Number);
	const w = width ?? vbW;
	return /* @__PURE__ */ jsx("svg", {
		width: w,
		height: w / vbW * vbH,
		viewBox: logo.viewBox,
		fill: "none",
		xmlns: "http://www.w3.org/2000/svg",
		className,
		...props,
		children: logo.paths.map((p, i) => /* @__PURE__ */ jsx("path", { ...p }, i))
	});
}
